-- Part 7 (difficulty-uplift pass): online MCQ bank (comp_mcq_questions) hard (difficulty=3) items
-- for civil_engineer and project_manager. Same root cause/mechanism as
-- mcq_part7_hard_hse_site_supervisor_seed.sql. civil_engineer was at 9/42 hard (21.4%) and
-- project_manager 9/42 (21.4%), both under the bank-wide ~24% hard share and the exam generator's
-- 25% quota. civil_engineer adds 7 items on topics that had zero difficulty=3 coverage yet
-- (rebar clear spacing, formwork-removal sequencing, erosion control, QC batch traceability,
-- foundation-alignment survey, temporary access-road bearing capacity, culvert design return
-- period) -> ~33% hard. project_manager's topics already had exactly one hard item each, so this
-- adds a second, structurally different item per topic (different facts, different scenario shape
-- - verified against the existing 8 project_manager difficulty=3 stems before drafting, e.g. not
-- another "two crews simultaneously" or "EAC calculation" item) -> ~33% hard.
-- Domain grounding: ACI 318 (rebar clear spacing), ACI 347 (formwork removal timing), erosion &
-- sediment control practice, concrete QC batch-traceability practice, hydraulic culvert design
-- return-period practice for civil_engineer; ERP drill practice, float/critical-path management,
-- pipeline drying/dew-point specification practice, Variation Order management, weld-reject SPC
-- trend analysis, stakeholder management practice, and FIDIC Sub-Clause 4.12 (Unforeseeable
-- Physical Conditions) for project_manager.
-- Anti-guessability: correct_option rotated 0..3 per row via the same technique as
-- supabase/seed/mcq_questions_seed.sql; no scenario shape repeats within this batch, the three
-- earlier Part 7 batches, or project_manager's existing difficulty=3 items. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'civil_engineer', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "میلگرد", 3, "طبق ACI 318، حداقل فاصله آزاد بین میلگردهای موازی در یک لایه معمولاً برابر بزرگترین مقدار از کدام موارد است؟", ["همیشه یک عدد ثابت ۱۰ میلی‌متر صرف‌نظر از قطر میلگرد یا اندازه سنگدانه", "قطر اسمی میلگرد، ۲۵ میلی‌متر، یا ۴/۳ برابر حداکثر اندازه اسمی سنگدانه درشت — هر کدام بزرگ‌تر باشد", "همیشه نصف قطر میلگرد بدون توجه به سنگدانه", "فقط به تشخیص کارگر آرماتوربند بستگی دارد"], 1, "ACI 318 حداقل فاصله آزاد میلگرد را بزرگترین مقدار از قطر اسمی میلگرد، ۲۵ میلی‌متر، یا ۴/۳ حداکثر اندازه سنگدانه درشت تعیین می‌کند تا از تراکم مناسب بتن اطراف میلگرد اطمینان حاصل شود.", "ACI 318 (Minimum Clear Spacing of Reinforcement)"],
["TECHNICAL", "قالب‌بندی", 3, "طبق رویه معمول زمان‌بندی قالب‌برداری، زمان مجاز باز کردن قالب جانبی ستون (بدون تحمل بار سازه‌ای) در مقایسه با قالب زیر تیر/دال باربر (با تحمل بار سازه‌ای) چگونه است؟", ["هر دو دقیقاً باید هم‌زمان و در یک زمان باز شوند", "قالب جانبی غیرباربر (مثل ستون) معمولاً زودتر از قالب زیر اعضای باربر خمشی (تیر/دال) باز می‌شود، چون دومی باید تا رسیدن بتن به مقاومت کافی برای تحمل بار خودش و بارهای اجرایی نگه داشته شود", "قالب زیر تیر/دال همیشه زودتر از قالب جانبی ستون باز می‌شود", "زمان باز کردن هیچ ارتباطی با نوع عضو سازه‌ای ندارد"], 1, "قالب جانبی اعضایی که بار سازه‌ای مستقیم تحمل نمی‌کنند می‌تواند زودتر باز شود، در حالی که قالب زیر اعضای خمشی باربر باید تا کسب مقاومت کافی بتن برای تحمل وزن خود و بارهای اجرایی نگه داشته شود.", "ACI 347 (Formwork Removal Timing)"],
["SCENARIO", "کنترل فرسایش و احیای حریم", 3, "پس از تکمیل خاکریزی حریم خط لوله در منطقه‌ای با شیب متوسط، بارش شدید باران پیش از احیای کامل پوشش گیاهی رخ می‌دهد و آثار اولیه فرسایش سطحی دیده می‌شود. اقدام درست کدام است؟", ["نادیده گرفتن چون فرسایش سطحی جزئی طبیعی است", "اجرای فوری اقدامات کنترل فرسایش موقت (مثل بلوک‌های رسوب‌گیر یا پوشش موقت) پیش از تشدید فرسایش و از دست رفتن خاک سطحی بیشتر", "تاخیر در اقدام تا پایان کامل فصل بارندگی", "افزایش شیب حریم برای تسریع زهکشی سطحی"], 1, "فرسایش سطحی اولیه در حریم تازه خاکریزی‌شده باید فوراً با اقدامات کنترل فرسایش موقت مدیریت شود؛ افزایش شیب زهکشی سطحی را تسریع اما ریسک فرسایش را نیز افزایش می‌دهد و اقدام نادرستی است.", "رویه کنترل فرسایش و احیای حریم (Erosion & Sediment Control)"],
["TECHNICAL", "مدیریت کیفیت و مستندات", 3, "چرا ثبت دقیق نتایج آزمایش‌های کنترل کیفیت بتن (اسلامپ، دما، مقاومت کیوب) به‌طور همزمان با هر بچ بتن‌ریزی، به‌جای ثبت خلاصه در پایان روز، اهمیت دارد؟", ["فقط یک الزام اداری بدون تاثیر فنی واقعی", "برای امکان ردیابی دقیق هر بچ به محل مشخص بتن‌ریزی‌شده در صورت بروز مشکل کیفی بعدی در آن بخش خاص از سازه", "چون ثبت خلاصه پایان روز همیشه دقیق‌تر است", "فقط برای کاهش حجم کاغذبازی"], 1, "ثبت هم‌زمان با هر بچ امکان ردیابی دقیق ارتباط بین نتیجه آزمایش کیفیت و محل مشخص بتن‌ریزی‌شده را فراهم می‌کند؛ ثبت خلاصه پایان روز این ارتباط دقیق را از دست می‌دهد و شناسایی محل دقیق در صورت بروز مشکل بعدی دشوار می‌شود.", "رویه کنترل کیفیت بتن‌ریزی و ردیابی بچ"],
["TECHNICAL", "نقشه‌برداری", 3, "در کنترل هم‌محوری یک ردیف فونداسیون تجهیزات دوار، چرا کنترل نقشه‌برداری باید هم مختصات افقی (X,Y) و هم تراز ارتفاعی (Z) را به‌طور مستقل بررسی کند؟", ["چون فقط مختصات افقی برای تجهیزات دوار اهمیت دارد", "چون انحراف در هرکدام از این دو بعد به‌طور مستقل می‌تواند باعث عدم هم‌محوری و تنش مخرب روی شفت/کوپلینگ تجهیز شود، حتی اگر بعد دیگر کاملاً دقیق باشد", "چون فقط تراز ارتفاعی اهمیت دارد و مختصات افقی نیازی به کنترل ندارد", "چون این دو مقدار همیشه به‌طور خودکار با هم صحیح می‌شوند"], 1, "خطای مستقل در هر یک از ابعاد افقی یا ارتفاعی می‌تواند به‌تنهایی باعث عدم هم‌محوری تجهیز دوار و تنش مخرب روی شفت/کوپلینگ شود؛ بنابراین هر دو باید مستقل و دقیق کنترل شوند.", "رویه کنترل نقشه‌برداری هم‌محوری فونداسیون تجهیزات دوار"],
["TECHNICAL", "راه دسترسی", 3, "چرا طراحی راه دسترسی موقت پروژه باید ظرفیت باربری کافی برای عبور تجهیزات سنگین را در نظر بگیرد، حتی اگر مسیر فقط موقتی باشد؟", ["چون ظاهر راه اهمیت بیشتری از عملکرد آن دارد", "چون نشست یا خرابی موضعی راه زیر بار سنگین می‌تواند باعث توقف عملیات حیاتی، آسیب به تجهیز یا حادثه ایمنی شود، صرف‌نظر از موقت بودن مسیر", "چون راه‌های موقت هیچ‌وقت زیر بار سنگین قرار نمی‌گیرند", "چون فقط راه‌های دائمی نیاز به طراحی ظرفیت باربری دارند"], 1, "نشست یا خرابی راه دسترسی موقت زیر بار سنگین می‌تواند عملیات حیاتی را متوقف یا حادثه ایمنی جدی ایجاد کند؛ موقت بودن مسیر نافی نیاز به طراحی مناسب ظرفیت باربری آن نیست.", "رویه طراحی راه دسترسی موقت پروژه"],
["TECHNICAL", "آبرو و زهکشی", 3, "چرا اندازه‌گذاری هیدرولیکی یک آبرو عبوری از زیر جاده دسترسی باید بر مبنای دبی سیل با دوره بازگشت طراحی (مثلاً ۲۵ یا ۵۰ ساله) باشد، نه صرفاً بر مبنای حداکثر بارندگی مشاهده‌شده اخیر؟", ["چون بارندگی اخیر همیشه بزرگترین سیل ممکن را نشان می‌دهد", "چون طراحی مبتنی بر دوره بازگشت آماری، ریسک سرریز/آسیب سازه‌ای را در بازه عمر طراحی پروژه به‌صورت مهندسی‌شده کنترل می‌کند، در حالی که مشاهده اخیر ممکن است نماینده کل طیف احتمالی رویدادها نباشد", "چون هزینه طراحی صرفاً بر اساس بارندگی اخیر کمتر است", "دوره بازگشت طراحی هیچ کاربردی در طراحی آبرو ندارد"], 1, "طراحی هیدرولیکی مبتنی بر دوره بازگشت آماری، ریسک سرریز و آسیب سازه‌ای را در طول عمر طراحی پروژه به شکل مهندسی‌شده کنترل می‌کند؛ یک رویداد بارندگی اخیر لزوماً نماینده طیف کامل احتمالات آماری نیست.", "رویه طراحی هیدرولیکی آبرو / دوره بازگشت سیل طراحی"]
]$mcq$::jsonb) with ordinality t(x, n)
cross join lateral (select ((((n - 1) % 4)::int - (x ->> 5)::int + 4) % 4) as k) r
on conflict (job_role, md5(stem_fa)) do nothing;

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'project_manager', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "HSE، مدیریت ریسک و آمادگی اضطراری", 3, "طرح آمادگی اضطراری پروژه طی یک سال گذشته هرگز از طریق مانور عملی (Drill) آزمایش نشده و فقط به‌صورت مستند در فایل موجود است. مدیر پروژه چه تصمیمی باید بگیرد؟", ["کافی دانستن وجود مستند مکتوب طرح بدون نیاز به مانور عملی", "برنامه‌ریزی و اجرای مانور عملی دوره‌ای برای صحه‌گذاری واقعی کارایی طرح و آمادگی تیم، نه صرفاً اتکا به مستند مکتوب", "تاخیر مانور تا وقوع یک حادثه واقعی برای تست طبیعی طرح", "واگذاری کامل مسئولیت آمادگی اضطراری به پیمانکار بدون نظارت"], 1, "طرح آمادگی اضطراری که هرگز با مانور عملی تست نشده، ضعف‌های پنهان (ارتباطات، نقش‌ها، زمان واکنش) خود را آشکار نمی‌کند؛ مانور دوره‌ای برای صحه‌گذاری واقعی کارایی طرح ضروری است.", "رویه آمادگی و واکنش اضطراری (ERP) / مانور تمرینی دوره‌ای"],
["TECHNICAL", "برنامه‌ریزی، پیشرفت و بازیابی تأخیر", 3, "تحلیل مسیر بحرانی برنامه پروژه نشان می‌دهد یک فعالیت غیربحرانی با شناوری (Float) زیاد، دو هفته تاخیر دارد اما فعالیت‌های بحرانی اصلی بدون تغییر باقی مانده‌اند. اولویت مدیریتی مدیر پروژه کدام است؟", ["تخصیص فوری منابع اضافی برای جبران تاخیر فعالیت غیربحرانی به هر قیمتی", "پایش تاخیر فعالیت غیربحرانی در حد مصرف شناوری آن بدون اختلال در منابع فعالیت‌های بحرانی، مگر شناوری آن رو به اتمام باشد", "توقف فوری کل پروژه تا رفع تاخیر آن فعالیت", "نادیده گرفتن کامل تاخیر چون فعالیت بحرانی نیست"], 1, "تاخیر فعالیت غیربحرانی در محدوده شناوری آن، تاریخ اتمام پروژه را به خطر نمی‌اندازد؛ تخصیص منابع اضافی غیرضروری به آن، منابع پروژه را از فعالیت‌های واقعاً بحرانی منحرف می‌کند و باید پایش شود تا شناوری رو به اتمام نرود.", "اصول مدیریت مسیر بحرانی و شناوری (Float Management)"],
["TECHNICAL", "دانش اجرایی خط لوله و راه‌اندازی", 3, "در مرحله پیش‌راه‌اندازی خط لوله، پیمانکار پیشنهاد می‌کند خشک‌کردن خط (Drying) با نقطه شبنم هدف بالاتر از مقدار مشخصات فنی برای صرفه‌جویی در زمان انجام شود، با استدلال اینکه سیال انتقالی خشک است. تصمیم درست مدیر پروژه کدام است؟", ["پذیرش پیشنهاد چون سیال انتقالی خشک اعلام شده است", "رد پیشنهاد و الزام دستیابی به نقطه شبنم مشخصات فنی طراحی، مگر تغییر رسماً توسط مهندسی/طراح ارزیابی و تایید شود", "واگذاری تصمیم کامل به پیمانکار چون او مجری مستقیم است", "تعویق تصمیم تا بعد از راه‌اندازی کامل"], 1, "نقطه شبنم مشخصات فنی برای کنترل ریسک‌های خوردگی/هیدرات در طول عمر خط طراحی شده و نباید بدون ارزیابی و تایید رسمی مهندسی تغییر کند، صرف‌نظر از استدلال اپراتوری پیمانکار.", "رویه پیش‌راه‌اندازی خط لوله (Pipeline Drying/Dew Point Specification)"],
["JUDGMENT", "راهبری پروژه و مدیریت قرارداد", 3, "کارفرما درخواست غیررسمی (فقط ایمیل عادی، نه دستور تغییر رسمی) برای انجام یک کار اضافی خارج از محدوده قرارداد می‌دهد. رویکرد حرفه‌ای مدیر پروژه‌ی پیمانکار کدام است؟", ["اجرای فوری کار بر مبنای ایمیل غیررسمی بدون پیگیری بیشتر", "درخواست صدور دستور تغییر رسمی (Variation Order) طبق مفاد قرارداد پیش از اجرای کار، برای حفظ حق مطالبه هزینه/زمان اضافی", "رد کامل انجام کار بدون هیچ مکاتبه‌ای", "اجرای کار و امیدواری به تسویه غیررسمی بعدی"], 1, "اجرای کار اضافی بدون دستور تغییر رسمی می‌تواند حق مطالبه هزینه و زمان اضافی پیمانکار را از بین ببرد؛ رویه صحیح درخواست رسمی‌سازی طبق مفاد قرارداد پیش از اجراست.", "مدیریت دستور تغییر قراردادی (Variation/Change Order Management)"],
